// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
        c.initialize();
    }

    function testFuzz_property(address newOwner) public {
        // Admissible domain: any non-zero address can become the new owner.
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != address(this)); // keep caller distinct from new owner

        vm.prank(address(this)); // current owner after initialize
        c.transferOwnership(newOwner);

        // General rule: after transferOwnership(newOwner), the owner is exactly newOwner.
        assertTrue(c.owner() == newOwner, "owner must equal the newOwner passed in");
    }
}
